import { dirname } from "path";
import { fileURLToPath } from "url";
import { FlatCompat } from "@eslint/eslintrc";

const __dirname = dirname(fileURLToPath(import.meta.url));

const compat = new FlatCompat({
  baseDirectory: __dirname,
});

// eslint-config-next ships as a legacy (.eslintrc-style) config — bridged
// into ESLint 9's flat config via FlatCompat, the documented approach for
// Next.js projects until eslint-config-next ships native flat config.
const eslintConfig = [
  ...compat.extends("next/core-web-vitals", "next/typescript"),
  {
    // next-env.d.ts is regenerated by `next build`/`next dev` and must
    // not be hand-edited — Next.js's own docs say to leave it alone, so
    // it's excluded from lint the same as the .next build output.
    ignores: [".next/**", "node_modules/**", "next-env.d.ts"],
  },
  {
    // Hand-written test fakes intentionally leave interface parameters
    // unused (e.g. `async findByUserId(_userId: string)`) when a fake only
    // needs to satisfy the full repository interface for a couple of
    // methods — the `_` prefix is the established convention for that.
    rules: {
      "@typescript-eslint/no-unused-vars": ["warn", { argsIgnorePattern: "^_" }],
    },
  },
];

export default eslintConfig;
